INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (23, 8, N'Xe ô tô; máy kéo; xe mô tô hai bánh; xe mô tô ba bánh; xe gắn máy; xe cơ giới dùng cho người khuyết tật và xe máy chuyên dùng; xe đạp, xe đạp máy, xe đạp điện.', 0, 1);
