INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (396, 125, N'Trong quá trình di chuyển không nên dùng phanh trước tránh làm khóa bánh dẫn hướng.', 0, 2);
