INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (588, 186, N'Báo hiệu đường có gồ giảm tốc phía trước.', 0, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (589, 187, N'Để báo trước gần tới đoạn đường có hiện tượng đất đá từ trên ta luy dương sụt lở bất ngờ gây nguy hiểm cho xe cộ và người đi đường.', 1, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (590, 187, N'Để báo trước nơi có kết cấu mặt đường rời rạc, khi phương tiện đi qua, làm cho các viên đá, sỏi văng lên gây nguy hiểm và mất an toàn cho người và phương tiện tham gia giao thông.', 0, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (591, 187, N'Để cảnh báo những đoạn nền đường yếu, đoạn đường đang theo dõi lún mà việc vận hành xe ở tốc độ cao có thể gây nguy hiểm.', 0, 3);
