SET XACT_ABORT ON;

-- Đảm bảo session không còn bật IDENTITY_INSERT từ lần chạy script bị lỗi trước đó.
IF OBJECT_ID('dap_an', 'U') IS NOT NULL SET IDENTITY_INSERT dap_an OFF;
IF OBJECT_ID('cau_hoi', 'U') IS NOT NULL SET IDENTITY_INSERT cau_hoi OFF;
IF OBJECT_ID('files', 'U') IS NOT NULL SET IDENTITY_INSERT files OFF;
IF OBJECT_ID('file_usages', 'U') IS NOT NULL SET IDENTITY_INSERT file_usages OFF;

IF COL_LENGTH('de_thi', 'loai_de_thi') IS NULL
BEGIN
    EXEC(N'ALTER TABLE de_thi ADD loai_de_thi NVARCHAR(50) NULL;');
END;

IF COL_LENGTH('de_thi', 'loai_de_thi') IS NOT NULL
BEGIN
    EXEC(N'UPDATE de_thi SET loai_de_thi = ISNULL(loai_de_thi, N''thi_thu'');');
END;

IF COL_LENGTH('cau_hoi', 'giai_thich_dap_an') IS NULL
BEGIN
    EXEC(N'ALTER TABLE cau_hoi ADD giai_thich_dap_an NVARCHAR(2000) NULL;');
END;

-- Cho phép user thi thử trực tiếp mà không cần tạo hồ sơ học viên.
-- bai_thi vẫn có thể gắn hoc_vien_id cho kỳ thi thật, nhưng thi_thu sẽ gắn nguoi_dung_id.
IF COL_LENGTH('bai_thi', 'nguoi_dung_id') IS NULL
BEGIN
    EXEC(N'ALTER TABLE bai_thi ADD nguoi_dung_id BIGINT NULL;');
END;

IF COL_LENGTH('bai_thi', 'hoc_vien_id') IS NOT NULL
BEGIN
    EXEC(N'ALTER TABLE bai_thi ALTER COLUMN hoc_vien_id BIGINT NULL;');
END;

IF COL_LENGTH('bai_thi', 'nguoi_dung_id') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'ix_bai_thi_nguoi_dung_id' AND object_id = OBJECT_ID('bai_thi'))
BEGIN
    EXEC(N'CREATE INDEX ix_bai_thi_nguoi_dung_id ON bai_thi(nguoi_dung_id);');
END;

IF COL_LENGTH('bai_thi', 'nguoi_dung_id') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.foreign_keys WHERE name = 'fk_bai_thi_nguoi_dung')
BEGIN
    EXEC(N'ALTER TABLE bai_thi WITH CHECK ADD CONSTRAINT fk_bai_thi_nguoi_dung FOREIGN KEY (nguoi_dung_id) REFERENCES nguoi_dung(id);');
END;

BEGIN TRANSACTION;

DELETE FROM chi_tiet_bai_thi;
DELETE FROM phien_on_tap_cau_hoi;
DELETE FROM de_thi_cau_hoi;

IF OBJECT_ID('file_usages', 'U') IS NOT NULL
BEGIN
    DELETE FROM file_usages
    WHERE entity_name = 'cau_hoi';
END;

IF OBJECT_ID('files', 'U') IS NOT NULL
BEGIN
    DELETE FROM files
    WHERE public_url LIKE '/assets/%';
END;

DELETE FROM dap_an;
DELETE FROM cau_hoi;

DBCC CHECKIDENT ('dap_an', RESEED, 0);
DBCC CHECKIDENT ('cau_hoi', RESEED, 0);
DBCC CHECKIDENT ('chi_tiet_bai_thi', RESEED, 0);
DBCC CHECKIDENT ('phien_on_tap_cau_hoi', RESEED, 0);
DBCC CHECKIDENT ('de_thi_cau_hoi', RESEED, 0);
IF OBJECT_ID('file_usages', 'U') IS NOT NULL DBCC CHECKIDENT ('file_usages', RESEED, 0);
IF OBJECT_ID('files', 'U') IS NOT NULL DBCC CHECKIDENT ('files', RESEED, 0);

